from contextlib import asynccontextmanager
from fastapi import FastAPI

resources: dict[str, str] = {}
events: list[str] = []

@asynccontextmanager
async def lifespan(app: FastAPI):
    resources["model"] = "ready"
    events.append("startup")
    yield
    resources.clear()
    events.append("shutdown")

app = FastAPI(lifespan=lifespan)

@app.get("/ready")
def ready():
    return {"model": resources.get("model")}

from functools import lru_cache
from typing import Annotated
from fastapi import Depends, FastAPI
from pydantic_settings import BaseSettings, SettingsConfigDict

class Settings(BaseSettings):
    app_name: str = "Learning API"
    debug: bool = False
    model_config = SettingsConfigDict(env_prefix="")

@lru_cache
def get_settings() -> Settings:
    return Settings()

SettingsDep = Annotated[Settings, Depends(get_settings)]
app = FastAPI()

@app.get("/info")
def info(settings: SettingsDep):
    return {"app_name": settings.app_name, "debug": settings.debug}

from urllib.parse import parse_qs
from a2wsgi import WSGIMiddleware
from fastapi import FastAPI

def legacy_wsgi(environ, start_response):
    name = parse_qs(environ.get("QUERY_STRING", "")).get("name", ["World"])[0]
    body = f"Hello {name} from WSGI".encode()
    start_response("200 OK", [("Content-Type", "text/plain; charset=utf-8"), ("Content-Length", str(len(body)))])
    return [body]

app = FastAPI()

@app.get("/v2")
def v2():
    return {"api": "fastapi"}

app.mount("/legacy", WSGIMiddleware(legacy_wsgi))
